from utils.retry import retry

def test_retry_succeeds_first_attempt():
    call_count = 0
    def operation():
        nonlocal call_count
        call_count += 1
        return "success"
    assert retry(operation) == "success"
    assert call_count == 1

def test_retry_succeeds_after_one_failure():
    call_count = 0
    def operation():
        nonlocal call_count
        call_count += 1
        if call_count == 1:
            raise ValueError("fail once")
        return "success"
    assert retry(operation) == "success"
    assert call_count == 2

def test_retry_succeeds_after_two_failures():
    call_count = 0
    def operation():
        nonlocal call_count
        call_count += 1
        if call_count <= 2:
            raise ValueError("fail twice")
        return "success"
    assert retry(operation) == "success"
    assert call_count == 3

def test_retry_raises_last_error_after_three_failures():
    call_count = 0
    with pytest.raises(ValueError) as excinfo:
        def operation():
            nonlocal call_count
            call_count += 1
            raise ValueError(f"fail {call_count}")
        retry(operation)
    assert "fail 3" in str(excinfo.value)
    assert call_count == 3
"
